/** Pure Connect 4 rules. Slots are indexed top-to-bottom, left-to-right. */
export const ROWS=6, COLS=7, EMPTY=-1;
export const FORMATS={single:{label:'Single match',target:1},bo3:{label:'Best of 3',target:2},bo5:{label:'Best of 5',target:3},bo7:{label:'Best of 7',target:4},first10:{label:'First to 10 wins',target:10}};
export const uid=()=>globalThis.crypto?.randomUUID?.()??`${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const emptyBoard=()=>Array(42).fill(EMPTY);
export const legalMoves=b=>[3,2,4,1,5,0,6].filter(c=>b[c]===EMPTY);
export function landingRow(b,c){if(!Number.isInteger(c)||c<0||c>=7)return -1;for(let r=5;r>=0;r--)if(b[r*7+c]===EMPTY)return r;return -1;}
export function winningLines(b){const lines=[];for(let r=0;r<6;r++)for(let c=0;c<7;c++){const p=b[r*7+c];if(p===EMPTY)continue;for(const [dr,dc] of [[0,1],[1,0],[1,1],[1,-1]]){const rr=r+dr*3,cc=c+dc*3;if(rr<0||rr>=6||cc<0||cc>=7)continue;const ids=Array.from({length:4},(_,i)=>(r+dr*i)*7+c+dc*i);if(ids.every(i=>b[i]===p))lines.push(ids);}}return lines;}
export function cleanConfig(c={}){const name=(n,d)=>typeof n==='string'&&n.trim()?n.trim().slice(0,24):d;return{mode:c.mode==='ai'?'ai':'local',names:[name(c.names?.[0],'Player 1'),name(c.names?.[1],c.mode==='ai'?'Computer':'Player 2')],colors:c.colors?.[0]==='yellow'?['yellow','red']:['red','yellow'],format:FORMATS[c.format]?c.format:'single',alternate:c.alternate!==false,difficulty:['easy','medium','hard'].includes(c.difficulty)?c.difficulty:'medium'};}
export function makeRound(starter=0,id=uid()){return{id,starter,board:emptyBoard(),moves:[],turn:starter,status:'playing',winner:null,lines:[]};}
export function playRound(round,col){if(round.status!=='playing')return round;const row=landingRow(round.board,col);if(row<0)return round;const board=[...round.board],player=round.turn;board[row*7+col]=player;const lines=winningLines(board),status=lines.length?'won':board.every(v=>v!==EMPTY)?'draw':'playing';return{...round,board,moves:[...round.moves,{col,row,player}],turn:status==='playing'?1-player:player,status,winner:status==='won'?player:null,lines};}
export function replayRound(starter,columns,id){let r=makeRound(starter,id);if(!Array.isArray(columns)||columns.length>42)throw Error('Invalid moves');for(const c of columns){const next=playRound(r,c);if(next===r)throw Error('Illegal saved move');r=next;}return r;}
export function derive(m){const completed=[...m.rounds,...(m.current.status!=='playing'?[m.current]:[])],scores=[0,0];let draws=0;for(const r of completed){if(r.winner===null)draws++;else scores[r.winner]++;}const target=FORMATS[m.config.format].target,champion=scores.findIndex(s=>s>=target),complete=champion>=0||(m.config.format==='single'&&completed.length>0);return{...m,scores,draws,champion:champion<0?null:champion,complete,roundNumber:m.rounds.length+1};}
export function newMatch(config){return derive({version:1,id:uid(),config:cleanConfig(config),rounds:[],current:makeRound()});}
export function drop(m,col){if(m.complete||m.current.status!=='playing')return m;const current=playRound(m.current,col);return current===m.current?m:derive({...m,current});}
export function nextRound(m){if(m.complete||m.current.status==='playing')return m;const rounds=[...m.rounds,m.current];return derive({...m,rounds,current:makeRound(m.config.alternate?rounds.length%2:0)});}
export function abandonRound(m){if(m.current.status!=='playing')return m;return derive({...m,current:makeRound(m.current.starter)});}
export function undoCount(m){const ms=m.current.moves;if(m.config.mode==='local')return ms.length?1:0;for(let i=ms.length-1;i>=0;i--)if(ms[i].player===0)return ms.length-i;return 0;}
export function undo(m){const n=undoCount(m);if(!n)return m;const r=m.current;return derive({...m,current:replayRound(r.starter,r.moves.slice(0,-n).map(x=>x.col),r.id)});}
export function serialize(m){return{version:1,id:m.id,config:m.config,rounds:m.rounds.map(r=>({id:r.id,columns:r.moves.map(x=>x.col)})),current:{id:m.current.id,columns:m.current.moves.map(x=>x.col)}};}
export function restore(raw){try{if(!raw||raw.version!==1||typeof raw.id!=='string'||raw.id.length>100||!Array.isArray(raw.rounds)||raw.rounds.length>10000||!raw.current||!FORMATS[raw.config?.format])return null;const config=cleanConfig(raw.config);let m=derive({version:1,id:raw.id,config,rounds:[],current:makeRound()});const seen=new Set();for(const [i,item] of [...raw.rounds,raw.current].entries()){if(typeof item.id!=='string'||item.id.length>100||seen.has(item.id)||m.complete)throw Error('Invalid saved round');seen.add(item.id);const r=replayRound(config.alternate?i%2:0,item.columns,item.id);if(i<raw.rounds.length&&r.status==='playing')throw Error('Unfinished past round');m=derive({...m,current:r});if(i<raw.rounds.length){if(m.complete)throw Error('Moves after match ended');m={...m,rounds:[...m.rounds,r],current:makeRound()};}}return derive(m);}catch{return null;}}
export function matchEvents(m){const rs=[...m.rounds,...(m.current.status!=='playing'?[m.current]:[])];return rs.map((r,i)=>({id:r.id,matchId:m.id,color:r.winner===null?null:m.config.colors[r.winner],moves:r.moves.length,matchComplete:m.complete&&i===rs.length-1}));}
export function syncEvents(events,m){const fresh=matchEvents(m);const ids=new Set(fresh.map(e=>e.id));const times=new Map(events.map(e=>[e.id,e.time]));const kept=events.filter(e=>e.matchId!==m.id);return [...kept,...fresh.map((e,i)=>({...e,time:times.get(e.id)??Date.now()+i}))].sort((a,b)=>a.time-b.time);}
export function statistics(events){let red=0,yellow=0,draws=0,moves=0,matches=0,streak=0,longest=0,last=null,fastest=Infinity;for(const e of events){moves+=e.moves;if(e.matchComplete)matches++;if(e.color==='red')red++;else if(e.color==='yellow')yellow++;else draws++;if(e.color){streak=last===e.color?streak+1:1;last=e.color;longest=Math.max(longest,streak);fastest=Math.min(fastest,e.moves);}else{streak=0;last=null;}}return{rounds:events.length,red,yellow,draws,matches,longest,average:events.length?(moves/events.length).toFixed(1):'—',fastest:fastest===Infinity?'—':fastest};}
